item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic a,
    input  logic b,
    input  logic cin,
    output logic cout,
    output logic sum
);
    assign sum  = a "'^ b ''^ cin;
    assign cout = (a & b) | (a & cin) | (b & cin);
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'"'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic a, b, cin;
    wire cout, sum;
    integer i;
    integer expected;
    TopModule dut (.a(a), .b(b), .cin(cin), .cout(cout), .sum(sum));
    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            {a, b, cin} = i[2:0];
            expected = int'"'(a) + int'(b) + int'(cin);
            #1;
            if ({cout, sum} "'!== expected[1:0])
                $fatal(1, "FAIL input=%b%b%b expected=%b actual=%b", a, b, cin, expected[1:0], {cout, sum});
        end
        $display("PASS: all 8 full-adder input combinations");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "FAIL: testbench timeout");
    end
endmodule
EOF
timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
'

